            return res.status(400).json({ error: 'limit must be a positive integer' });
        }
        limit = Math.min(parsed, MAX_LIMIT);
    }

    // --- cursor: decode or start at the beginning ---
    let cursor = null;
    if (req.query.after !== undefined && req.query.after !== '') {
